/* 获取女主时装图片 */
window.getCostumeImg = function(name, index){
    var key = name + '_' + index;
    if(window.COSTUME_IMAGES && window.COSTUME_IMAGES[key]){
        return 'data:image/webp;base64,' + window.COSTUME_IMAGES[key];
    }
    return 'costume/' + name + '_' + index + '.jpg';
};

/* 获取怪物图片 */
window.getGuaiImg = function(isBoss, seg){
    var key = (isBoss ? 'b' : 'm') + seg;
    if(window.GUAI_IMAGES && window.GUAI_IMAGES[key]){
        return 'data:image/webp;base64,' + window.GUAI_IMAGES[key];
    }
    return 'guai/' + (isBoss ? 'b' : 'm') + seg + '.jpg';
};
