/* ========== 邮件系统 ========== */
function initMail(){
    if(typeof P==='undefined'||!P)return;
    if(!P.mail)P.mail={list:[],lastRead:0};
    if(!P.mail.list)P.mail.list=[];
}

/* ========== 节日自动发放礼包 ========== */
window.checkFestivalGift=function(){
    try{
        var today=new Date();
        var month=today.getMonth()+1;
        var day=today.getDate();
        var dateStr=month+"-"+day;
        
        /* 新手礼包只发一次 */
        if(!P.hasClaimedNewbieGift){
            /* 发一个新手福利礼包 */
            sendMail(
                "🎁 新手福利礼包",
                "尊敬的道友：\n\n欢迎来到问道长生！这是我们为你准备的新手福利礼包，祝你修仙之路一帆风顺！\n\n奖励内容：灵石10万、仙玉100、金币100万、红色装备四件套礼包×1",
                [
                    {type:"money",name:"灵石",count:100000},
                    {type:"yu",name:"仙玉",count:100},
                    {type:"gold",name:"金币",count:1000000},
                    {name:"红色装备四件套礼包",count:1}
                ]
            );
            P.hasClaimedNewbieGift=true;
            saveGame();
        }
        
        /* 节日列表：key=月-日，value=祝福语 */
        var festivals={
            "1-1":"元旦快乐！新的一年，祝你修为大进，仙途无量！",
            "2-14":"情人节快乐！愿你道侣相伴，双修有成！",
            "3-8":"女神节快乐！祝所有女修士容颜永驻，道心通明！",
            "5-1":"劳动节快乐！修仙不辍，劳动最光荣！",
            "5-4":"青年节快乐！少年侠气，交结五都雄！",
            "6-1":"儿童节快乐！愿你永葆赤子之心，修行之路无忧！",
            "7-1":"建党节快乐！初心不改，道心永恒！",
            "8-1":"建军节快乐！铁血丹心，所向披靡！",
            "9-10":"教师节快乐！一日为师，终身为父！",
            "10-1":"国庆节快乐！普天同庆，国运昌隆！",
            "12-24":"平安夜快乐！愿你平安喜乐，道途坦荡！",
            "12-25":"圣诞节快乐！愿你有个温暖的冬天！"
        };
        
        /* 节日礼包奖励：10万灵石，100仙玉，500金币，混沌宝箱一个 */
        var festivalRewards=[
            {type:"money",name:"灵石",count:100000},
            {type:"yu",name:"仙玉",count:100},
            {type:"gold",name:"金币",count:500},
            {name:"混沌宝箱",count:1}
        ];
        
        /* 检查今天是不是节日 */
        var festivalName=null;
        var festivalText=null;
        for(var key in festivals){
            if(key===dateStr){
                festivalName=key;
                festivalText=festivals[key];
                break;
            }
        }
        
        /* 如果是节日，检查是不是今天已经发过了 */
        if(festivalName){
            if(!P.lastFestivalGift||P.lastFestivalGift!==dateStr){
                /* 发节日礼包邮件 */
                sendMail(
                    "🎉 节日礼包："+festivalName,
                    "尊敬的道友：\n\n"+festivalText+"\n\n这是我们为你准备的节日礼包，请注意查收！",
                    festivalRewards
                );
                P.lastFestivalGift=dateStr;
                saveGame();
            }
        }
        
        /* 周一礼包：10万灵石，100万金币，50仙玉，金色宝箱一个 */
        var dayOfWeek=today.getDay();
        if(dayOfWeek===1){/* 周一 */
            var mondayDate=today.toDateString();
            if(!P.lastMondayGift||P.lastMondayGift!==mondayDate){
                var mondayRewards=[
                    {type:"money",name:"灵石",count:100000},
                    {type:"gold",name:"金币",count:1000000},
                    {type:"yu",name:"仙玉",count:50},
                    {name:"金色宝箱",count:1}
                ];
                sendMail(
                    "📅 周一福利礼包",
                    "尊敬的道友：\n\n新的一周开始了！祝你本周修为精进，收获满满！\n\n这是我们为你准备的周一福利礼包，请注意查收！",
                    mondayRewards
                );
                P.lastMondayGift=mondayDate;
                saveGame();
            }
        }
        
    }catch(e){console.error("检查节日礼包错误:",e);}
};

/* ========== 通用给道具函数 ========== */
window.giveItem=function(name,num,icon,desc){
    if(!P.bag)P.bag=[];
    var f=P.bag.find(function(x){return x.name===name;});
    if(f){f.num+=num;}else{
        var item={name:name,num:num};
        if(icon)item.icon=icon;
        if(desc)item.desc=desc;
        P.bag.push(item);
    }
};

/* ========== 登录邮箱奖励弹窗 ========== */
window.checkLoginMailReward=function(){
    try{
        initMail();
        var unclaimed=P.mail.list.filter(function(m){return !m.claimed&&m.rewards&&m.rewards.length>0;});
        if(unclaimed.length===0)return;
        
        /* 只提示未领取的周一礼包或节日礼包 */
        var hasNewGift=unclaimed.some(function(m){
            return m.title.indexOf("周一福利")>=0||m.title.indexOf("节日礼包")>=0;
        });
        
        if(hasNewGift){
            if(typeof navOpen==="function"){
                navOpen("mail");
                showToast("您有新的福利礼包未领取，已打开邮箱","gold");
            }
        }
    }catch(e){console.error("检查邮箱奖励错误:",e);}
};
window.claimLoginMailReward=function(mailId){
    try{
        initMail();
        var mail=P.mail.list.find(function(m){return m.id===mailId;});
        if(!mail||mail.claimed)return;
        var msg=[];
        mail.rewards.forEach(function(r){
            var amount=r.count||r.num||0;
            if(r.type==="money"||r.type==="lingshi"||r.name==="灵石"){P.money=(P.money||0)+amount;msg.push("灵石+"+amount);}
            else if(r.type==="gold"||r.name==="金币"){P.gold=(P.gold||0)+amount;msg.push("金币+"+amount);}
            else if(r.type==="yu"||r.name==="仙玉"){P.yu=(P.yu||0)+amount;msg.push("仙玉+"+amount);}
            else{giveItem(r.name,amount,r.icon,r.desc);msg.push(r.name+"×"+amount);}
        });
        mail.claimed=true;
        mail.read=true;
        saveGame();
        if(typeof refresh==="function")refresh();
        /* 刷新福利页仙玉显示 */
        if(typeof openMonthCardPanel==="function" && window.currentTab==="monthcard"){
            openMonthCardPanel();
        }
        closeModal();
        showToast("领取成功："+msg.join("，"),"gold");
    }catch(e){console.error("领取邮箱奖励错误:",e);}
};

window.sendMail=function(title,content,rewards){
    initMail();
    var mail={
        id:"mail_"+Date.now()+"_"+Math.floor(Math.random()*10000),
        title:title,
        content:content,
        rewards:rewards||[],
        time:Date.now(),
        read:false,
        claimed:false
    };
    P.mail.list.unshift(mail);
    /* 最多保留50封邮件 */
    if(P.mail.list.length>50)P.mail.list=P.mail.list.slice(0,50);
    try{saveGame();}catch(e){}
    showToast("收到新邮件："+title,"gold");
};
window.htmlMail=function(){
    initMail();
    var h='<div class="panel"><h3 style="color:#5a3a1a">📬 邮件</h3>';
    if(P.mail.list.length===0){
        h+='<div style="text-align:center;color:#999;padding:30px;">暂无邮件</div>';
    }else{
        P.mail.list.forEach(function(mail,i){
            var readCls=mail.read?"":"font-weight:bold;";
            var icon=mail.claimed?"📭":(mail.read?"📫":"📨");
            h+='<div class="card" style="margin-bottom:6px;cursor:pointer;" onclick="openMailDetail(\''+mail.id+'\')">';
            h+='<div style="display:flex;align-items:center;gap:8px;">';
            h+='<div style="font-size:24px;">'+icon+'</div>';
            h+='<div style="flex:1;">';
            h+='<div style="'+readCls+'color:#5a3a1a;font-size:13px;">'+mail.title+'</div>';
            var date=new Date(mail.time);
            h+='<div style="font-size:10px;color:#999;">'+date.getMonth()+'/'+date.getDate()+' '+date.getHours()+':'+String(date.getMinutes()).padStart(2,'0')+'</div>';
            h+='</div>';
            if(mail.rewards&&mail.rewards.length>0&&!mail.claimed){
                h+='<div style="color:#d4a030;font-size:11px;">🎁 奖励</div>';
            }
            h+='</div>';
            h+='</div>';
        });
    }
    /* 一键领取 */
    var unclaimed=P.mail.list.filter(function(m){return !m.claimed&&m.rewards&&m.rewards.length>0;});
    if(unclaimed.length>0){
        h+='<button class="btn btn-gold" style="width:100%;margin-top:10px;" onclick="claimAllMail()">🎁 一键领取'+unclaimed.length+'封邮件奖励</button>';
    }
    h+='</div>';
    return h;
};
window.openMailDetail=function(mailId){
    initMail();
    var mail=P.mail.list.find(function(m){return m.id===mailId;});
    if(!mail)return;
    mail.read=true;
    try{saveGame();}catch(e){}
    var h='<div class="modal" id="mailDetailModal" style="z-index:999999;"><div class="modal-content" style="max-width:380px;max-height:70vh;overflow-y:auto;">';
    h+='<div class="modal-title">📬 '+mail.title+'</div>';
    h+='<div style="padding:15px;">';
    var date=new Date(mail.time);
    h+='<div style="font-size:11px;color:#999;margin-bottom:10px;">'+date.getFullYear()+'/'+(date.getMonth()+1)+'/'+date.getDate()+' '+date.getHours()+':'+String(date.getMinutes()).padStart(2,'0')+'</div>';
    h+='<div style="font-size:13px;line-height:1.6;color:#5a3a1a;white-space:pre-wrap;">'+mail.content+'</div>';
    if(mail.rewards&&mail.rewards.length>0){
        h+='<div style="margin-top:15px;padding:10px;background:rgba(212,160,48,0.1);border-radius:6px;">';
        h+='<div style="font-weight:bold;color:#d4a030;margin-bottom:8px;">🎁 邮件奖励</div>';
        mail.rewards.forEach(function(r){
            h+='<div style="font-size:12px;color:#5a3a1a;margin:4px 0;">• '+(r.icon||'📦')+' '+r.name+' ×'+(r.count||r.num||0)+'</div>';
        });
        if(!mail.claimed){
            h+='<button class="btn btn-gold" style="width:100%;margin-top:10px;" onclick="claimMailReward(\''+mail.id+'\')">领取奖励</button>';
        }else{
            h+='<div style="text-align:center;color:#888;margin-top:10px;font-size:12px;">✓ 已领取</div>';
        }
        h+='</div>';
    }
    h+='</div>';
    h+='<div style="display:flex;gap:8px;margin-top:10px;">';
    h+='<button class="btn" style="flex:1;" onclick="deleteMail(\''+mail.id+'\')">🗑 删除</button>';
    h+='<button class="btn btn-gold" style="flex:1;" onclick="closeModal(\'mailDetailModal\')">关闭</button>';
    h+='</div>';
    h+='</div></div>';
    var old=document.getElementById("mailDetailModal");if(old)old.remove();
    document.body.insertAdjacentHTML("beforeend",h);
};
window.claimMailReward=function(mailId){
    initMail();
    var mail=P.mail.list.find(function(m){return m.id===mailId;});
    if(!mail||mail.claimed||!mail.rewards)return;
    var msg=[];
    mail.rewards.forEach(function(r){
        var amount=r.count||r.num||0;
        if(r.type==="money"||r.type==="lingshi"||r.name==="灵石"){P.money=(P.money||0)+amount;msg.push("灵石+"+amount);}
        else if(r.type==="gold"||r.name==="金币"){if(!P.gold&&P.gold!==0)P.gold=0;P.gold+=amount;msg.push("金币+"+amount);}
        else if(r.type==="contrib"||r.name==="宗门贡献"){if(!P.sect)P.sect={};if(!P.sect.contribution)P.sect.contribution=0;P.sect.contribution+=amount;msg.push("宗门贡献+"+amount);}
        else{giveItem(r.name,amount,r.icon,r.desc);msg.push(r.name+"×"+amount);}
    });
    mail.claimed=true;
    try{saveGame();}catch(e){}
    if(typeof refreshStats==="function")refreshStats();
    if(typeof refresh==="function")refresh();
    showToast("领取成功："+msg.join("，"),"gold");
    setTimeout(function(){
        try{if(typeof renderTab==="function")renderTab();}catch(e){}
    },100);
    closeModal("mailDetailModal");
    if(typeof navOpen==="function")navOpen("mail");
};
window.claimAllMail=function(){
    initMail();
    if(!P.money&&P.money!==0)P.money=0;
    if(!P.gold&&P.gold!==0)P.gold=0;
    if(!P.sect)P.sect={};
    if(!P.sect.contribution)P.sect.contribution=0;
    var total=0;
    var rewardMsgs=[];
    P.mail.list.forEach(function(mail){
        if(!mail.claimed&&mail.rewards&&mail.rewards.length>0){
            mail.rewards.forEach(function(r){
                var cnt=parseInt(r.count||r.num)||0;
                if(r.type==="money"||r.type==="lingshi"||r.name==="灵石"){P.money+=cnt;rewardMsgs.push("灵石+"+cnt);}
                else if(r.type==="gold"||r.name==="金币"){P.gold+=cnt;rewardMsgs.push("金币+"+cnt);}
                else if(r.type==="contrib"||r.name==="宗门贡献"){P.sect.contribution+=cnt;rewardMsgs.push("宗门贡献+"+cnt);}
                else{giveItem(r.name,cnt,r.icon,r.desc);rewardMsgs.push(r.name+"×"+cnt);}
            });
            mail.claimed=true;
            total++;
        }
    });
    if(total===0){showToast("没有可领取的邮件奖励","red");return;}
    try{saveGame();}catch(e){}
    if(typeof refreshStats==="function")refreshStats();
    if(typeof refresh==="function")refresh();
    showToast("领取成功："+rewardMsgs.join("，"),"gold");
    setTimeout(function(){
        try{if(typeof renderTab==="function")renderTab();}catch(e){}
    },100);
    if(typeof navOpen==="function")navOpen("mail");
};
window.navOpenMail=function(){
    var mm=document.getElementById("moreMenu");if(mm)mm.classList.remove("show");
    P.curTab="mail";
    renderTab();
    var popup=document.getElementById("sidePopup");
    var inner=document.getElementById("sidePopupInner");
    document.getElementById("sidePopupTitle").textContent="📬 邮件";
    popup.classList.add("show");
    var heroBar=document.querySelector(".top-bar")||document.querySelector(".hero-bar-compact");
    var heroH=heroBar?heroBar.offsetHeight:0;
    var tipBar=document.querySelector(".tip-bar");
    var tipH=tipBar?tipBar.offsetHeight:0;
    var topSpace=heroH+tipH+12;
    var bottomSpace=70;
    var maxH=window.innerHeight-topSpace-bottomSpace;
    inner.style.maxHeight=Math.max(200,maxH)+"px";
    inner.style.bottom=bottomSpace+"px";
    var body=document.getElementById("sidePopupBody");
    if(body)body.scrollTop=0;
}

/* 邮件删除功能 */
window.deleteMail=function(mailId){
    initMail();
    var idx=P.mail.list.findIndex(function(m){return m.id===mailId;});
    if(idx>=0){
        P.mail.list.splice(idx,1);
        try{saveGame();}catch(e){}
        showToast("邮件已删除","gold");
    }
    closeModal("mailDetailModal");
    if(typeof navOpen==="function")navOpen("mail");
}

/* ========== 好友系统 ========== */
window.initFriends=function(){
    if(!P.friends)P.friends={list:[],requests:[]};
};
window.htmlFriend=function(){
    initFriends();
    var h='<div class="panel"><h3 style="color:#5a3a1a">👥 好友</h3>';
    h+='<div style="display:flex;gap:6px;margin-bottom:10px;">';
    h+='<input id="friendNameInput" class="input" style="flex:1;" placeholder="输入道号添加好友">';
    h+='<button class="btn btn-sm btn-gold" onclick="addFriend()">添加</button>';
    h+='</div>';
    if(P.friends.requests.length>0){
        h+='<h4 style="color:#dc143c;">好友请求 ('+P.friends.requests.length+')</h4>';
        P.friends.requests.forEach(function(req,i){
            h+='<div class="tower-stat"><span>'+req.name+'</span><span><button class="btn btn-sm" onclick="acceptFriend('+i+')">接受</button> <button class="btn btn-sm" onclick="rejectFriend('+i+')">拒绝</button></span></div>';
        });
    }
    h+='<h4 style="color:#5a3a1a;">好友列表 ('+P.friends.list.length+')</h4>';
    if(P.friends.list.length===0){
        h+='<p style="text-align:center;color:#999;padding:20px;">暂无好友，快去添加吧！</p>';
    }else{
        P.friends.list.forEach(function(f,i){
            h+='<div class="tower-stat"><span>'+f.name+' ('+f.realm+')</span><span><button class="btn btn-sm" onclick="chatFriend('+i+')">私聊</button> <button class="btn btn-sm" onclick="removeFriend('+i+')">删除</button></span></div>';
        });
    }
    h+='</div>';
    return h;
};
window.addFriend=function(){
    var inputs=document.querySelectorAll("#friendNameInput");
    var input=inputs[inputs.length-1];
    if(!input){showToast("请输入道号","red");return;}
    var name=input.value.trim();
    if(!name){showToast("请输入道号","red");return;}
    if(name===P.name){showToast("不能添加自己为好友","red");return;}
    if(P.friends.list.find(function(f){return f.name===name;})){showToast("已经是好友了","red");return;}
    var realms=["练气","筑基","金丹","元婴","化神","炼虚","合体","大乘","渡劫","仙人"];
    P.friends.list.push({name:name,realm:realms[Math.floor(Math.random()*10)],level:Math.floor(Math.random()*100)+1,online:Math.random()>0.3});
    try{saveGame();}catch(e){}
    showToast("好友添加成功","gold");
    input.value="";
    // 刷新好友列表显示
    var modals=document.querySelectorAll("[style*='z-index:9999']");
    if(modals.length>0){
        var lastModal=modals[modals.length-1];
        var innerDiv=lastModal.querySelector("div");
        if(innerDiv){
            innerDiv.innerHTML=htmlFriend()+'<button class="btn" style="width:100%;background:#8b7355;color:#fff;" onclick="this.parentElement.parentElement.remove()">关闭</button>';
        }
    }
};
window.acceptFriend=function(i){
    var req=P.friends.requests[i];
    P.friends.list.push({name:req.name,realm:req.realm,level:req.level,online:true});
    P.friends.requests.splice(i,1);
    try{saveGame();}catch(e){}
    showToast("已接受好友请求","gold");
    renderTab();
};
window.rejectFriend=function(i){
    P.friends.requests.splice(i,1);
    try{saveGame();}catch(e){}
    showToast("已拒绝好友请求","red");
    renderTab();
};
window.removeFriend=function(i){
    P.friends.list.splice(i,1);
    try{saveGame();}catch(e){}
    showToast("已删除好友","red");
    renderTab();
};
window.navOpenFriend=function(){
    var mm=document.getElementById("moreMenu");if(mm)mm.classList.remove("show");
    var modal=document.createElement("div");
    modal.style.cssText="position:fixed;top:0;left:0;width:100%;height:100%;background:rgba(0,0,0,0.7);z-index:9999;display:flex;align-items:center;justify-content:center;";
    modal.innerHTML='<div style="background:#fff;border:2px solid #8b7355;border-radius:10px;width:90%;max-width:400px;max-height:80vh;overflow-y:auto;">'+htmlFriend()+'<button class="btn" style="width:100%;background:#8b7355;color:#fff;" onclick="this.parentElement.parentElement.remove()">关闭</button></div>';
    modal.onclick=function(e){if(e.target===modal)modal.remove();};
    document.body.appendChild(modal);
};
window.chatFriend=function(i){
    var f=P.friends.list[i];
    showToast("正在打开与"+f.name+"的私聊...","gold");
}

/* ========== 宗门聊天频道 ========== */
window.initSectChat=function(){
    if(!P.sectChat)P.sectChat={messages:[]};
    if(P.sectChat.messages.length===0){
        var names=["掌门","大师兄","二师姐","三师弟","小师妹","长老","护法","弟子甲","弟子乙","弟子丙"];
        var msgs=["大家好啊！","今天修炼了吗？","有人一起打副本吗？","宗门任务做完了吗？","新来了不少弟子啊","宗门宝藏又刷新了","谁有多余的丹药？","下周宗门大比准备好了吗？","我突破了！","恭喜恭喜！"];
        for(var i=0;i<5;i++){
            P.sectChat.messages.push({name:names[Math.floor(Math.random()*names.length)],msg:msgs[Math.floor(Math.random()*msgs.length)],time:Date.now()-Math.floor(Math.random()*3600000)});
        }
    }
};
window.htmlSectChat=function(){
    initSectChat();
    var h='<div class="panel"><h3 style="color:#5a3a1a">💬 宗门频道</h3>';
    h+='<div id="sectChatMessages" style="height:300px;overflow-y:auto;border:1px solid #ddd;border-radius:3px;padding:8px;margin-bottom:10px;background:#f9f9f9;">';
    P.sectChat.messages.forEach(function(m){
        var time=new Date(m.time);
        var timeStr=time.getHours()+":"+String(time.getMinutes()).padStart(2,"0");
        h+='<div style="margin-bottom:6px;"><span style="color:#d4a030;font-weight:bold;">'+m.name+'</span> <span style="color:#999;font-size:12px;">'+timeStr+'</span><br><span style="color:#333;">'+m.msg+'</span></div>';
    });
    h+='</div>';
    h+='<div style="display:flex;gap:6px;">';
    h+='<input id="sectChatInput" class="input" style="flex:1;" placeholder="输入消息..." onkeypress="if(event.key===\'Enter\')sendSectMsg()">';
    h+='<button class="btn btn-sm btn-gold" onclick="sendSectMsg()">发送</button>';
    h+='</div></div>';
    return h;
};
window.sendSectMsg=function(){
    var inputs=document.querySelectorAll("#sectChatInput");
    var input=inputs[inputs.length-1];
    if(!input)return;
    var msg=input.value.trim();
    if(!msg)return;
    P.sectChat.messages.push({name:P.name,msg:msg,time:Date.now()});
    if(P.sectChat.messages.length>100)P.sectChat.messages.shift();
    try{saveGame();}catch(e){}
    input.value="";
    // 直接更新弹窗中的聊天记录
    var modal=document.getElementById("sectChatModal");
    if(modal){
        var innerDiv=modal.querySelector("div");
        if(innerDiv){
            innerDiv.innerHTML=htmlSectChat()+'<button class="btn" style="width:100%;background:#8b7355;color:#fff;" onclick="document.getElementById(\'sectChatModal\').remove()">关闭</button>';
        }
    }
    // 滚动到底部
    setTimeout(function(){
        var boxes=document.querySelectorAll("#sectChatMessages");
        var box=boxes[boxes.length-1];
        if(box)box.scrollTop=box.scrollHeight;
    },100);
};
window.navOpenSectChat=function(){
    var mm=document.getElementById("moreMenu");if(mm)mm.classList.remove("show");
    var modal=document.createElement("div");
    modal.id="sectChatModal";
    modal.style.cssText="position:fixed;top:0;left:0;width:100%;height:100%;background:rgba(0,0,0,0.7);z-index:9999;display:flex;align-items:center;justify-content:center;";
    modal.innerHTML='<div style="background:#fff;border:2px solid #8b7355;border-radius:10px;width:90%;max-width:400px;max-height:80vh;overflow-y:auto;">'+htmlSectChat()+'<button class="btn" style="width:100%;background:#8b7355;color:#fff;" onclick="document.getElementById(\'sectChatModal\').remove()">关闭</button></div>';
    modal.onclick=function(e){if(e.target===modal)modal.remove();};
    document.body.appendChild(modal);
    setTimeout(function(){
        var box=document.getElementById("sectChatMessages");
        if(box)box.scrollTop=box.scrollHeight;
    },100);
};

/* ========== 功能引导系统 ========== */
window.initGuide=function(){
    if(!P.guide)P.guide={step:0,completed:false};
};
window.guideSteps=[
    {title:"欢迎来到问道长生",content:"这是一款修仙放置游戏，点击闯关开始你的修仙之旅！",target:"battleArea"},
    {title:"角色面板",content:"这里显示你的角色信息，包括气血、灵力、悟性、福缘等属性。",target:"heroPanel"},
    {title:"修炼系统",content:"点击修炼按钮可以提升修为，修为满后可以突破境界。",target:"xiulianBtn"},
    {title:"装备系统",content:"在装备界面可以抽奖获得装备，穿戴装备可以提升战力。",target:"equipBtn"},
    {title:"道侣系统",content:"在道侣界面可以结识道侣，道侣可以协助你战斗。",target:"daolvBtn"},
    {title:"宗门系统",content:"加入宗门可以获得宗门福利，还能和宗门成员聊天。",target:"sectBtn"},
    {title:"背包系统",content:"在背包中可以查看和使用你的道具。",target:"bagBtn"},
    {title:"引导完成",content:"恭喜你完成了新手引导！祝你修仙之路顺利！",target:null}
];
window.showGuide=function(step){
    initGuide();
    if(step===undefined)step=P.guide.step;
    if(step>=guideSteps.length){P.guide.completed=true;try{saveGame();}catch(e){}return;}
    var g=guideSteps[step];
    var modal=document.createElement("div");
    modal.id="guideModal";
    modal.style.cssText="position:fixed;top:0;left:0;width:100%;height:100%;background:rgba(0,0,0,0.8);z-index:20000;display:flex;align-items:center;justify-content:center;";
    modal.innerHTML='<div style="background:#fff;border:2px solid #d4a030;border-radius:10px;width:90%;max-width:400px;padding:20px;text-align:center;">'+
        '<h3 style="color:#d4a030;margin-bottom:10px;">'+g.title+'</h3>'+
        '<p style="color:#333;margin-bottom:20px;line-height:1.6;">'+g.content+'</p>'+
        '<div style="display:flex;gap:10px;justify-content:center;">'+
        '<button class="btn" style="flex:1;" onclick="skipGuide()">跳过引导</button>'+
        '<button class="btn btn-gold" style="flex:1;" onclick="nextGuide()">下一步</button>'+
        '</div></div>';
    document.body.appendChild(modal);
};
window.nextGuide=function(){
    P.guide.step++;
    try{saveGame();}catch(e){}
    var modal=document.getElementById("guideModal");
    if(modal)modal.remove();
    if(P.guide.step<guideSteps.length){
        showGuide(P.guide.step);
    }else{
        P.guide.completed=true;
        try{saveGame();}catch(e){}
        showToast("新手引导完成！","gold");
    }
};
window.skipGuide=function(){
    P.guide.completed=true;
    P.guide.step=guideSteps.length;
    try{saveGame();}catch(e){}
    var modal=document.getElementById("guideModal");
    if(modal)modal.remove();
    showToast("已跳过新手引导","gold");
};
window.resetGuide=function(){
    P.guide={step:0,completed:false};
    try{saveGame();}catch(e){}
    showGuide(0);
}

/* ========== 界面记忆系统 ========== */
window.saveUIState=function(){
    var uiState={
        curTab:P.curTab,
        lastOpen:Date.now()
    };
    try{
        localStorage.setItem("wdcs_uiState",JSON.stringify(uiState));
    }catch(e){}
};
window.loadUIState=function(){
    try{
        var data=localStorage.getItem("wdcs_uiState");
        if(data){
            var uiState=JSON.parse(data);
            if(uiState.curTab&&uiState.curTab!=="xiu"){
                // 恢复上次的标签页
                setTimeout(function(){
                    P.curTab=uiState.curTab;
                    renderTab();
                },500);
            }
        }
    }catch(e){}
};
window.clearUIState=function(){
    try{
        localStorage.removeItem("wdcs_uiState");
    }catch(e){}
}

