/* ========== 排行榜系统（简单可靠版） ========== */
window.openRankPanel=function(type){
    if(!type)type="zhanli";
    var mm=document.getElementById("moreMenu");if(mm)mm.classList.remove("show");
    
    // 生成排行榜数据
    var names=["剑无痕","李青云","王重阳","张道陵","赵灵儿","林月如","孙悟空","哪吒","杨戬","雷震子",
               "鬼谷子","袁天罡","李淳风","张三丰","吕洞宾","何仙姑","蓝采和","韩湘子","曹国舅","汉钟离",
               "铁拐李","张果老","清虚真人","紫阳真人","太一真人","九幽冥主","玄天圣女","紫霞仙子","青霞仙子","斗战圣佛",
               "白衣书生","黑衣剑客","红衣仙子","绿衣道人","青衣女子","黄衣老者","紫衣少女","橙衣少年","粉衣佳人",
               "玄衣道人","素衣女子","锦衣公子","布衣书生","蓑衣渔夫","樵夫老者","牧童少年","绣女佳人","镖师大汉","掌柜先生"];
    var realms=["练气","筑基","金丹","元婴","化神","炼虚","合体","大乘","渡劫","仙人","真仙","金仙"];
    var playerZhanli=P.zhanli||10000;
    var playerLv=P.lv||1;
    var playerMoney=P.money||0;
    var list=[];
    for(var i=0;i<50;i++){
        var name=names[Math.floor(Math.random()*names.length)];
        var realmIdx=Math.min(11,Math.max(0,Math.floor(Math.random()*10)+Math.floor(playerLv/12)-2+Math.floor(Math.random()*4)));
        var zhanli=Math.floor(playerZhanli*(0.5+Math.random()*1.5));
        var lv=realmIdx*12+Math.floor(Math.random()*12);
        var money=Math.floor(playerMoney*(0.3+Math.random()*2));
        list.push({name:name,zhanli:zhanli,lv:lv,realm:realms[realmIdx],money:money,isPlayer:false});
    }
    list.push({name:P.name||"我",zhanli:playerZhanli,lv:playerLv,realm:realms[Math.min(11,Math.floor(playerLv/12))],money:playerMoney,isPlayer:true});
    
    if(type==="zhanli")list.sort(function(a,b){return b.zhanli-a.zhanli;});
    else if(type==="lv")list.sort(function(a,b){return b.lv-a.lv;});
    else if(type==="money")list.sort(function(a,b){return b.money-a.money;});
    
    var typeLabel={zhanli:"战力榜",lv:"境界榜",money:"财富榜"};
    var h='<div style="padding:10px;">';
    h+='<h3 style="color:#8b4513;text-align:center;margin-bottom:10px;">🏆 '+typeLabel[type]+'</h3>';
    h+='<div style="display:flex;gap:6px;margin-bottom:10px;">';
    h+='<button class="btn btn-sm '+(type==="zhanli"?"btn-gold":"")+'" style="flex:1;" onclick="openRankPanel(\'zhanli\')">战力</button>';
    h+='<button class="btn btn-sm '+(type==="lv"?"btn-gold":"")+'" style="flex:1;" onclick="openRankPanel(\'lv\')">境界</button>';
    h+='<button class="btn btn-sm '+(type==="money"?"btn-gold":"")+'" style="flex:1;" onclick="openRankPanel(\'money\')">财富</button>';
    h+='</div>';
    list.slice(0,20).forEach(function(p,i){
        var medal=i===0?"👑":i===1?"🥈":i===2?"🥉":(i+1);
        var nameColor=i===0?"#d4a030":i===1?"#dc143c":i===2?"#800080":"#000";
        var bg=p.isPlayer?'style="background:#fff8dc;border:1px solid #d4a030;padding:6px;margin:2px 0;border-radius:3px;"':'style="background:#fff;padding:6px;margin:2px 0;border-bottom:1px solid #ddd;"';
        var val=type==="zhanli"?p.zhanli:type==="lv"?p.realm:p.money;
        var valLabel=type==="zhanli"?"战力":type==="lv"?"境界":"灵石";
        h+='<div '+bg+'><span style="color:'+nameColor+';">'+medal+' '+p.name+(p.isPlayer?" (我)":"")+'</span><span style="color:#8b4513;float:right;">'+valLabel+':'+val+'</span></div>';
    });
    h+='<button class="btn" style="width:100%;margin-top:10px;background:#8b7355;color:#fff;" onclick="closeModal(\'rankModal\')">关闭</button>';
    h+='</div>';
    
    // 直接创建弹窗显示
    var modal=document.getElementById("rankModal");
    if(!modal){
        modal=document.createElement("div");
        modal.id="rankModal";
        modal.className="modal-overlay";
        modal.style.cssText="position:fixed;top:0;left:0;width:100%;height:100%;background:rgba(0,0,0,0.7);z-index:9999;display:flex;align-items:center;justify-content:center;";
        modal.onclick=function(e){if(e.target===modal)modal.style.display="none";};
        document.body.appendChild(modal);
    }
    modal.innerHTML='<div style="background:#fff;color:#000;border:2px solid #8b7355;border-radius:10px;width:90%;max-width:400px;max-height:80vh;overflow-y:auto;">'+h+'</div>';
    modal.style.display="flex";
};


